    Turn(arm, x_axis, 0.3491, 0.2451)
    Turn(nozzle, x_axis, -0.3491, 0.2451)
    Sleep(330)
  end
end

local function buildArmStop()
  Turn(armbase, y_axis, 0, 4)
  Turn(arm, x_axis, 0, 4)
  Turn(nozzle, x_axis, 0, 4)
end

