function script.StartBuilding(heading, pitch)
  if heading then
    Turn(armbase, y_axis, heading, 2.0944)
    Turn(arm, x_axis, -pitch, 1.5708)
    Turn(armbase2, y_axis, heading, 2.0944)
    Turn(arm2, x_axis, -pitch, 1.5708)
    WaitForTurn(armbase, y_axis)
    WaitForTurn(arm, x_axis)
    WaitForTurn(armbase2, y_axis)
    WaitForTurn(arm2, x_axis)
  end
  Signal(SIG_BUILDARM)
  StartThread(buildArm)
  Signal(SIG_BUILDARM_2)
  StartThread(buildArm2)
  SetUnitValue(COB.INBUILDSTANCE, 1)
end

function script.StopBuilding()
  SetUnitValue(COB.INBUILDSTANCE, 0)
  Turn(armbase, y_axis, 0, 2.0944)
  Turn(arm, x_axis, 0, 1.5708)
  Turn(armbase2, y_axis, 0, 2.0944)
  Turn(arm2, x_axis, 0, 1.5708)
  Signal(SIG_BUILDARM)
  buildArmStop()
  Signal(SIG_BUILDARM_2)
  buildArm2Stop()
end

function script.QueryNanoPiece()
  return base
end

function script.Killed(recentDamage, maxHealth)
  Explode(base, SFX.SHATTER)
  return 1
end
